```go
package main

import (
    "errors"
    "fmt"
)

func divide(a, b int) (int, error) {
    if b == 0 { return 0, errors.New("division by zero") }
    return a / b, nil
}

func main() {
    value, err := divide(10, 2)
    fmt.Println(value, err)
}
```
The output is `5 <nil>`. Calling `divide(10, 0)` would return `0` plus a non-nil error; the caller must use the error to interpret the value.

```go
package main

import (
    "errors"
    "fmt"
    "strconv"
)

var ErrPort = errors.New("invalid port")

func port(text string) (int, error) {
    value, err := strconv.Atoi(text)
    if err != nil { return 0, fmt.Errorf("%w: %q", ErrPort, text) }
    return value, nil
}

func main() {
    _, err := port("abc")
    fmt.Println(errors.Is(err, ErrPort))
}
```
The output is `true`. The function returns no usable port, adds the input as context, and preserves a stable error identity.

```go
package main

import "fmt"

type SearchResult struct {
    Items []string
    NextCursor string
    Total int
}

func search() (SearchResult, error) {
    return SearchResult{Items: []string{"go"}, NextCursor: "page-2", Total: 9}, nil
}

func main() {
    result, err := search()
    fmt.Println(result.Items, result.NextCursor, result.Total, err)
}
```
The output names remain attached to the value: `[go] page-2 9 <nil>`. The error remains a separate status result by convention.

```go
package main

import "fmt"

func dimensions() (int, int) { return 4, 3 }
func area(width, height int) int { return width * height }

func main() {
    fmt.Println(area(dimensions()))
}
```
The output is `12`. The two results of `dimensions` fill the two parameters of `area` in order.
